CREATE COLUMN TABLE "TEST_AP"."MTH2V" ("MthAcctCod" NVARCHAR(15) NOT NULL , "IsInternal" NVARCHAR(1) DEFAULT 'E' NOT NULL , "MatchNum" INTEGER CS_INT NOT NULL , "BnkAcctCod" NVARCHAR(15) NOT NULL , "Sequence" INTEGER CS_INT NOT NULL , "DueDate" LONGDATE CS_LONGDATE, "Ref" NVARCHAR(27), "DebAmount" DECIMAL(21,6) CS_FIXED, "Memo" NVARCHAR(254), PRIMARY KEY ("MthAcctCod", "IsInternal", "MatchNum", "Sequence")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "MTH2V_SECONDARY" ON "TEST_AP"."MTH2V" ( "BnkAcctCod" ASC, "Sequence" ASC )